import{_ as a,C as o,o as r,c as n,E as i,a2 as s}from"./chunks/framework.BOeh4kYD.js";const y=JSON.parse('{"title":"A Proposed Procedure Is Not Yet Active Authority","description":"","frontmatter":{"title":"A Proposed Procedure Is Not Yet Active Authority","date":"2026-09-10","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"当智能体可以修改将指导未来执行的流程时，什么证据与状态隔离应决定一个提议的结构变化能否成为生效流程？","summary":"The right to propose a better procedure is not the right to activate it. Self-evolving systems need stable candidate identity, evidence separated from proposal generation, explicit adoption, durable rejection, expiry, and rollback.","sources":["research/analysis/Q-20260910-02-evidence-gated-self-evolving-procedure-adoption.md"],"item_id":"Q-20260910-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-10-proposed-procedure-not-active-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/industry/2026-09-10-proposed-procedure-not-active-authority.md","filePath":"en/industry/2026-09-10-proposed-procedure-not-active-authority.md","lastUpdated":1789042267000}'),c={name:"en/industry/2026-09-10-proposed-procedure-not-active-authority.md"};function d(l,e,p,h,u,m){const t=o("ArticleCover");return r(),n("div",null,[i(t,{image:"/assets/covers/daily-2026-09-10-proposed-procedure-not-active-authority-cover.png",kicker:"Industry Architecture · Daily Research",title:"A Proposed Procedure Is Not Yet Active Authority",summary:"The right to propose a better procedure is not the right to activate it. Self-evolving systems need stable candidate identity, evidence separated from proposal generation, explicit adoption, durable rejection, expiry, and rollback.",version:"Q-20260910-02",status:"Daily Runtime V5 · 2026-09-10",languageHref:"/zh/industry/2026-09-10-proposed-procedure-not-active-authority",languageLabel:"中文"}),e[0]||(e[0]=s('<h1 id="a-proposed-procedure-is-not-yet-active-authority" tabindex="-1">A Proposed Procedure Is Not Yet Active Authority <a class="header-anchor" href="#a-proposed-procedure-is-not-yet-active-authority" aria-label="Permalink to &quot;A Proposed Procedure Is Not Yet Active Authority&quot;">​</a></h1><p>After completing a task, an agent sees that its procedure took an unnecessary detour. It removes one step, adds a shortcut, and saves the revised structure for the next run. The change looks coherent and may genuinely improve efficiency.</p><p>But the system has done more than preserve a lesson. A procedure changes the ordering of future actions, tool selection, stopping conditions, and side effects. The right to propose that change is not the right to let it govern future work.</p><p>The central argument is: <strong>a self-evolving procedure must remain candidate control state until an explicit adoption gate evaluates evidence not used to generate the proposal. The active procedure needs a separate, stable identity until that gate passes.</strong></p><h2 id="procedure-change-is-control-deployment" tabindex="-1">Procedure Change Is Control Deployment <a class="header-anchor" href="#procedure-change-is-control-deployment" aria-label="Permalink to &quot;Procedure Change Is Control Deployment&quot;">​</a></h2><p>A note can inform later reasoning. Procedure state directly shapes behavior. It determines when a tool is called, what evidence is observed first, whether failure causes another attempt, and which condition closes the task. A procedure change can widen the effect surface even when the model and tool catalog remain fixed.</p><p>For that reason, modifying a procedure is closer to deploying a policy than editing prose. The highest-risk design lets the refiner overwrite active state directly. The system cannot freeze candidate identity, and it cannot prove that the object later evaluated is the object eventually activated.</p><p>The first boundary is simple: keep the current active identity frozen during execution. New structures created offline enter a candidate space. The proposer may explore freely, but proposal does not carry activation authority.</p><h2 id="why-held-out-evidence-matters" tabindex="-1">Why Held-Out Evidence Matters <a class="header-anchor" href="#why-held-out-evidence-matters" aria-label="Permalink to &quot;Why Held-Out Evidence Matters&quot;">​</a></h2><p>The same-day Research Object analyzes Procedural Graphs, a primary study that externalizes procedural knowledge as a directed attributed graph. The retained graph stays fixed during each inference episode. Between batches, an offline refiner generates a candidate that must pass structural checks and behavioral validation.</p><p>The validation examples are disjoint from the training trajectories that generated the mutation, and they are also separate from the final test set. A candidate replaces the retained graph only when mean validation performance matches or exceeds the baseline. The important feature is not one score. It is the evidence relationship: <strong>the material that causes a change cannot be the complete evidence authorizing that change.</strong></p><p>This separation prevents the system from treating improvement on the motivating examples as self-validating deployment proof. A proposed improvement becomes an object that can be rejected, not an automatically effective self-description.</p><h2 id="rejection-is-a-normal-outcome" tabindex="-1">Rejection Is a Normal Outcome <a class="header-anchor" href="#rejection-is-a-normal-outcome" aria-label="Permalink to &quot;Rejection Is a Normal Outcome&quot;">​</a></h2><p>The reported search trace is non-monotonic. Some rounds produce no committed update. One proposal fails structural validation. Another candidate is rejected when validation survival falls from ninety percent to eighty-five percent. Rejected candidates can remain as negative evidence without becoming the next active graph.</p><p>A self-evolving system that records only the final successful upgrade loses some of its most useful governance evidence. No-op rounds, malformed structures, and behavioral regressions show the boundary of the search process.</p><p>Rejected state should be durable but non-executable. It can inform later proposals, yet recovery, caching, or rollback must not confuse it with a previously accepted version. Otherwise preserving negative evidence creates a side door for activation.</p><h2 id="data-separation-is-not-adjudicator-independence" tabindex="-1">Data Separation Is Not Adjudicator Independence <a class="header-anchor" href="#data-separation-is-not-adjudicator-independence" aria-label="Permalink to &quot;Data Separation Is Not Adjudicator Independence&quot;">​</a></h2><p>Held-out samples create real evidence separation, but not complete independence. In the reported configurations, solving, guidance, and offline refinement can use the same underlying language model. Disjoint datasets reduce direct reuse of proposal-generating examples while shared model blind spots may remain.</p><p>Mean task performance also observes only the dimensions encoded by the metric. Rare authorization failures, irreversible effects, recovery regressions, or cost explosions can be diluted by ordinary successes. Structural validation catches explicit formation and reachability defects, but it does not prove that every semantic or safety constraint holds.</p><p>Two types of independence should remain distinct. Data independence asks whether acceptance evidence comes from the same examples that caused the proposal. Adjudicator independence asks whether evaluation can reveal systematic failures the proposer is unlikely to see. High-impact procedures often need both.</p><h2 id="what-a-minimum-adoption-contract-binds" tabindex="-1">What a Minimum Adoption Contract Binds <a class="header-anchor" href="#what-a-minimum-adoption-contract-binds" aria-label="Permalink to &quot;What a Minimum Adoption Contract Binds&quot;">​</a></h2><p>An auditable activation decision should bind at least these facts.</p><ul><li>Candidate identity: fixed content digest, version, generation provenance, and parent.</li><li>Active identity: unchanged until adoption completes and never aliased to a mutable candidate pointer.</li><li>Structural evidence: validator version, results, and explicitly uncovered constraints.</li><li>Behavioral evidence: validation examples, metric, baseline, failures, and uncertainty.</li><li>Decision authority: the person or mechanism allowed to move a candidate into active state.</li><li>Freshness: the model, tool, policy, and environment changes that expire prior evidence.</li><li>Rollback target: the previously accepted identity restored after an incident.</li><li>Rejection record: a visible failed candidate that never receives execution authority.</li></ul><p>The activation itself should be atomic. The system either continues to reference the old active identity or, after every gate passes, references the exact candidate that was evaluated. It cannot test one artifact and activate a later mutable descendant.</p><h2 id="passing-the-gate-is-not-permanent-proof" tabindex="-1">Passing the Gate Is Not Permanent Proof <a class="header-anchor" href="#passing-the-gate-is-not-permanent-proof" aria-label="Permalink to &quot;Passing the Gate Is Not Permanent Proof&quot;">​</a></h2><p>A common objection says that any candidate with a non-decreasing held-out score should be activated automatically. For low-risk, reversible settings with strong metric coverage, that rule can be a useful minimum. It is not a universal safety proof.</p><p>The validation set may be small. The benchmark may observe average completion while missing rare severe outcomes. The evaluator may share the proposer&#39;s model-level bias. Tool catalogs, permission policies, and operating environments also change, making old adoption evidence stale.</p><p>A more faithful lifecycle includes candidate, evaluating, rejected, adopted, stale, and revoked. Historical acceptance remains a fact, but it does not automatically become current authority after its dependencies change.</p><h2 id="boundaries-and-open-questions" tabindex="-1">Boundaries and Open Questions <a class="header-anchor" href="#boundaries-and-open-questions" aria-label="Permalink to &quot;Boundaries and Open Questions&quot;">​</a></h2><p>Procedural Graphs is recent primary research and does not prove that its exact mechanism fits every production system. The experiments do not establish concurrent-refiner safety, crash-consistent activation, signed adoption authority, or cross-system rollback after incidents. Structural validation also does not enforce every semantic constraint.</p><p>The supported conclusion is a minimum architecture boundary: separate candidate from active state, evaluate evidence not used to generate the proposal, keep rejected state non-executable, and bind acceptance to freshness and rollback. It does not support authorizing any high-impact procedure merely because average performance did not decline.</p><p>Open questions remain. Which safety and authorization dimensions must join task performance? When should admission require a different model, deterministic validator, or accountable human authority? How can a runtime prove byte-for-byte identity between the candidate evaluated and the object activated? What model, tool, policy, or environment changes expire evidence? After an incident, how should rollback and re-adoption remain one verifiable trajectory?</p><p><strong>Evidence and citation:</strong></p><ul><li><a href="https://arxiv.org/html/2609.09153v1" target="_blank" rel="noreferrer">Procedural Graphs primary study</a></li></ul>',34))])}const f=a(c,[["render",d]]);export{y as __pageData,f as default};
